"use client";

import { useEffect, useState, type ReactNode, type CSSProperties, type SetStateAction } from "react";
import { Activity, ArrowDown, ArrowRight, ArrowUp, Cable, Check, CheckCheck, CheckCircle2, ChevronRight, CircleHelp, Clock3, Copy, Download, Eye, EyeOff, FileJson, FileUp, Fingerprint, FlaskConical, KeyRound, LayoutDashboard, ListChecks, Loader2, LockKeyhole, Network, Pause, Play, Plus, Radio, RotateCcw, Router, Search, Server, Settings2, ShieldCheck, Square, Terminal, Trash2, Upload, Wifi, X, AlertTriangle } from "lucide-react";
import { SidebarProvider, Sidebar, SidebarHeader, SidebarContent, SidebarFooter, SidebarGroup, SidebarGroupLabel, SidebarMenu, SidebarMenuItem, SidebarMenuButton, SidebarTrigger, SidebarInset, useSidebar } from "@/components/ui/sidebar";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetDescription } from "@/components/ui/sheet";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Checkbox } from "@/components/ui/checkbox";
import { Switch } from "@/components/ui/switch";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Progress } from "@/components/ui/progress";
import { Toaster } from "@/components/ui/sonner";
import { toast } from "sonner";
import { initialModels, initialGroups, initialDevices, initialACS, previewCSV, simulateResults, type Model, type Group, type Credential, type Device, type ACS, type Run, type RunResult } from "./data";

import { useCloudState } from "./use-cloud-state";
import AgentPanel from "./agent-panel";
type View = "overview" | "models" | "credentials" | "devices" | "runs" | "acs" | "agent";
const nav: { id: View; label: string; icon: typeof Router }[] = [
  { id: "overview", label: "Visão geral", icon: LayoutDashboard },
  { id: "models", label: "Modelos e roteiros", icon: Router },
  { id: "credentials", label: "Credenciais de acesso", icon: KeyRound },
  { id: "devices", label: "Equipamentos", icon: Network },
  { id: "agent", label: "Agente local", icon: Terminal },
  { id: "runs", label: "Simulações", icon: Activity },
  { id: "acs", label: "Servidor ACS", icon: Server },
];
const titles: Record<View, [string, string]> = {
  agent: ["Agente local", "Prepare pacotes para sua rede e importe os resultados das execuções."],
  overview: ["Central de implantação", "Do primeiro acesso à confirmação no ACS, em um só lugar."],
  models: ["Modelos de equipamentos", "Um roteiro por modelo e firmware. Reutilize em toda a sua rede."],
  credentials: ["Credenciais de acesso", "Organize as combinações de usuário e senha que sua operação utiliza."],
  devices: ["Equipamentos", "Selecione os roteadores e ONUs que farão parte do próximo lote."],
  runs: ["Simulações", "Experimente o fluxo com cenários fictícios. O inventário real não é alterado."],
  acs: ["Servidor ACS", "Defina os parâmetros que serão aplicados aos equipamentos."],
};
function NavButton({ active, click, children }: { active: boolean; click: () => void; children: ReactNode }) {
  const { isMobile, setOpenMobile } = useSidebar();
  return <SidebarMenuButton className="nav-button" isActive={active} onClick={() => { click(); if (isMobile) setOpenMobile(false); }}>{children}</SidebarMenuButton>;
}
function uid(prefix: string) { return `${prefix}-${crypto.randomUUID()}`; }
function download(name: string, content: string, type = "application/json") {
  const url = URL.createObjectURL(new Blob([content], { type }));
  const a = document.createElement("a"); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
}
function Badge({ children, tone = "neutral" }: { children: ReactNode; tone?: string }) { return <span className={`badge ${tone}`}>{children}</span>; }
function Status({ value }: { value: string }) {
  const good = ["Confirmado no ACS", "Acesso validado", "Já configurado"].includes(value);
  const bad = ["Falha de login", "Sem acesso", "Sem credencial"].includes(value);
  return <Badge tone={good ? "green" : bad ? "red" : value === "Pendente" ? "neutral" : "amber"}>{good ? <CheckCircle2 /> : bad ? <AlertTriangle /> : <Clock3 />}{value}</Badge>;
}
function Pick({ value, onChange, items, label, className = "" }: { value: string; onChange: (v: string) => void; items: { value: string; label: string }[]; label: string; className?: string }) {
  return <Select value={value} onValueChange={onChange}><SelectTrigger aria-label={label} className={`pick ${className}`}><SelectValue placeholder={label} /></SelectTrigger><SelectContent position="popper">{items.map(item => <SelectItem value={item.value} key={item.value}>{item.label}</SelectItem>)}</SelectContent></Select>;
}
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label>; }
function Secret({ value, onChange, label = "Senha" }: { value: string; onChange: (value: string) => void; label?: string }) {
  const [show, setShow] = useState(false);
  return <div className="secret-input"><input aria-label={label} type={show ? "text" : "password"} autoComplete="off" value={value} onChange={e => onChange(e.target.value)} /><button type="button" className="icon-btn" aria-label={show ? "Ocultar senha" : "Mostrar senha"} onClick={() => setShow(!show)}>{show ? <EyeOff /> : <Eye />}</button></div>;
}
function Empty({ title, text, action }: { title: string; text: string; action?: ReactNode }) { return <div className="empty-state"><Search /><h3>{title}</h3><p>{text}</p>{action}</div>; }

export default function Console({ localMode = false }: { localMode?: boolean }) {
  const [view, setView] = useState<View>("overview");
  const cloud = useCloudState();
  const { models, groups, devices, acs } = cloud.state;
  const setModels = (v: SetStateAction<Model[]>) => cloud.update("models", v);
  const setGroups = (v: SetStateAction<Group[]>) => cloud.update("groups", v);
  const setDevices = (v: SetStateAction<Device[]>) => cloud.update("devices", v);
  const setACS = (v: SetStateAction<ACS>) => cloud.update("acs", v);
  const [runs, setRuns] = useState<Run[]>([]);
  const [query, setQuery] = useState("");
  const [brandFilter, setBrandFilter] = useState("all");
  const [deviceFilter, setDeviceFilter] = useState("all");
  const [selected, setSelected] = useState<string[]>([]);
  const [modal, setModal] = useState<"model" | "group" | "credential" | "import" | "run" | "help" | null>(null);
  const [editModel, setEditModel] = useState<Model | null>(null);
  const [detail, setDetail] = useState<Model | null>(null);
  const [groupId, setGroupId] = useState("g1");
  const [reveal, setReveal] = useState<string[]>([]);
  const [runTargets, setRunTargets] = useState<Device[]>([]);
  const [runId, setRunId] = useState<string | null>(null);
  const [resultDetail, setResultDetail] = useState<RunResult | null>(null);
  const group = groups.find(g => g.id === groupId) || groups[0];
  const pending = devices.filter(d => d.status !== "Confirmado no ACS" && d.status !== "Já configurado");
  const confirmed = devices.length - pending.length;
  const prepared = models.filter(m => m.ready).length;
  const activeRun = runs.find(r => r.id === runId) || runs[0];
  const busy = runs.some(r => r.state === "running" || r.state === "paused");
  const matchingModels = models.filter(m => `${m.brand} ${m.name} ${m.firmware}`.toLowerCase().includes(query.toLowerCase()) && (brandFilter === "all" || m.brand === brandFilter));
  const filteredDevices = devices.filter(d => {
    const m = models.find(m => m.id === d.model);
    return `${d.name} ${d.ip} ${m?.name} ${m?.brand}`.toLowerCase().includes(query.toLowerCase()) && (deviceFilter === "all" || (deviceFilter === "pending" ? !["Confirmado no ACS", "Já configurado"].includes(d.status) : deviceFilter === "done" ? ["Confirmado no ACS", "Já configurado"].includes(d.status) : ["Revisar modelo", "Falha de login", "Sem acesso", "Sem credencial"].includes(d.status)));
  });
  function navigate(next: View) { setView(next); setQuery(""); }
  function openRun(targets = selected.length ? devices.filter(d => selected.includes(d.id)) : pending) {
    if (busy) { navigate("runs"); toast.info("Conclua ou encerre a simulação atual antes de criar outro lote."); return; }
    if (!targets.length) { toast.info("Selecione pelo menos um equipamento na lista."); navigate("devices"); return; }
    setRunTargets(targets); setModal("run");
  }
  function startRun(name: string, mode: string) {
    const run: Run = { id: uid("run"), name, mode, acs: acs.url, date: new Date().toLocaleString("pt-BR"), results: simulateResults(runTargets, models, groups, mode), cursor: 0, state: "running" };
    setRuns(r => [run, ...r]); setRunId(run.id); setModal(null); navigate("runs");
  }
  useEffect(() => {
    const running = runs.find(r => r.state === "running"); if (!running) return;
    const timer = setTimeout(() => {
      const result = running.results[running.cursor];
      // Simulation never changes the persistent equipment inventory.
      void result;
      const finished = running.cursor + 1 >= running.results.length;
      setRuns(rs => rs.map(r => r.id === running.id ? { ...r, cursor: r.cursor + 1, state: finished ? "finished" : "running" } : r));
      if (finished) toast.success("Simulação concluída. O relatório está disponível.");
    }, 650);
    return () => clearTimeout(timer);
  }, [runs]);
  function saveModel(m: Model) {
    setModels(ms => ms.some(x => x.id === m.id) ? ms.map(x => x.id === m.id ? m : x) : [...ms, m]);
    setDevices(ds => ds.map(d => d.model === m.id && d.status === "Revisar modelo" && m.ready ? { ...d, status: "Pendente" } : d));
    setModal(null); setEditModel(null); toast.success("Alteração preparada. Acompanhe o indicador de salvamento.");
  }
  function reorder(id: string, direction: number) {
    const index = group.entries.findIndex(e => e.id === id), dest = index + direction;
    if (dest < 0 || dest >= group.entries.length) return;
    const entries = [...group.entries]; [entries[index], entries[dest]] = [entries[dest], entries[index]];
    setGroups(gs => gs.map(g => g.id === group.id ? { ...g, entries } : g));
  }
  function exportRun(run: Run) {
    const safeCell = (v: string) => '"' + (/^[=+@\-\t\r]/.test(v) ? "'" + v : v).replaceAll('"', '""') + '"';
    const rows = [["equipamento", "ip", "modelo", "status_simulado", "credencial_nome", "mensagem"], ...run.results.slice(0, run.cursor).map(r => [r.device, r.ip, r.model, r.status, r.credential || "", r.message])];
    download("relatorio-simulacao-acs.csv", "\uFEFF" + rows.map(r => r.map(safeCell).join(";")).join("\r\n"), "text/csv;charset=utf-8");
  }
  function renderDeviceTable(rows: Device[], selectable = false) {
    return <Table><TableHeader><TableRow>{selectable && <TableHead className="check-cell"><Checkbox aria-label="Selecionar equipamentos exibidos" checked={rows.length > 0 && rows.every(d => selected.includes(d.id)) ? true : rows.some(d => selected.includes(d.id)) ? "indeterminate" : false} onCheckedChange={checked => setSelected(s => checked ? [...new Set([...s, ...rows.map(d => d.id)])] : s.filter(id => !rows.some(d => d.id === id)))} /></TableHead>}<TableHead>Equipamento</TableHead><TableHead>Endereço IP</TableHead><TableHead>Modelo</TableHead><TableHead>Status</TableHead><TableHead><span className="sr-only">Detalhes</span></TableHead></TableRow></TableHeader><TableBody>{rows.map(d => { const m = models.find(m => m.id === d.model); return <TableRow key={d.id} data-state={selected.includes(d.id) ? "selected" : undefined}>{selectable && <TableCell className="check-cell"><Checkbox checked={selected.includes(d.id)} aria-label={`Selecionar ${d.name}`} onCheckedChange={checked => setSelected(s => checked ? [...s, d.id] : s.filter(id => id !== d.id))} /></TableCell>}<TableCell><div className="device-name"><span className="device-icon">{m?.type === "ONU" ? <Cable /> : <Router />}</span><strong>{d.name}</strong></div></TableCell><TableCell><span className="mono">{d.ip}</span><small className="port-label">:{d.port}</small></TableCell><TableCell><strong className="table-model">{m?.name}</strong><small className="block">{m?.brand}</small></TableCell><TableCell><Status value={d.status} /></TableCell><TableCell><button className="icon-btn" title="Ver modelo" aria-label={`Ver modelo de ${d.name}`} onClick={() => setDetail(m || null)}><ChevronRight /></button></TableCell></TableRow>; })}</TableBody></Table>;
  }

  if (!cloud.loaded) return <main className="startup"><Radio/><h1>ACS Pilot</h1><p>{cloud.error || "Carregando seus cadastros…"}</p>{cloud.error && <button className="btn primary" onClick={cloud.reload}>Tentar novamente</button>}</main>;
  return <SidebarProvider style={{ "--sidebar-width": "252px" } as CSSProperties}><Sidebar className="pilot-sidebar"><SidebarHeader className="brand-header"><div className="brand-mark"><Radio /></div><div className="wordmark">acs<span>pilot</span><small>NETWORK OPERATIONS</small></div></SidebarHeader><SidebarContent><div className="workspace-switch"><span className="workspace-avatar">N</span><div><strong>Minha operação</strong><small>Cadastros da sua operação</small></div><LockKeyhole /></div><SidebarGroup><SidebarGroupLabel>IMPLANTAÇÃO</SidebarGroupLabel><SidebarMenu>{nav.map((item, i) => <SidebarMenuItem key={item.id} className={i === 5 ? "nav-separated" : ""}><NavButton active={view === item.id} click={() => navigate(item.id)}><item.icon /><span>{item.label}</span>{item.id === "models" && <span className="nav-count">{models.length}</span>}{item.id === "runs" && busy && <span className="live-dot" />}</NavButton></SidebarMenuItem>)}</SidebarMenu></SidebarGroup></SidebarContent><SidebarFooter><div className="agent-card"><div><span className="agent-icon"><Terminal /></span><strong>Agente local</strong><span className="offline-dot" /></div><p>Execução por pacote</p><small>Exporte o lote e execute o agente na sua rede.</small></div><button className="help-button" onClick={() => setModal("help")}><CircleHelp />Como usar a plataforma<ChevronRight /></button><div className="profile"><span>OP</span><div><strong>Operador da rede</strong><small>Administrador</small></div><Badge>v0.2</Badge></div></SidebarFooter></Sidebar>
    <SidebarInset className="app-inset"><header className="topbar"><div className="breadcrumb"><SidebarTrigger className="sidebar-toggle" /><span>Workspace</span><ChevronRight /><strong>{nav.find(n => n.id === view)?.label}</strong></div><div className="topbar-right"><Badge tone="mint"><ShieldCheck />{localMode ? "Neste Mac" : "Base funcional"}</Badge><span className="top-avatar">OP</span></div></header><main className="main-content"><div className="page-heading"><div><span className="eyebrow">ACS PILOT / OPERAÇÃO</span><h1>{titles[view][0]}</h1><p>{titles[view][1]}</p></div><div className="heading-actions">{view === "models" ? <><button className="btn secondary" onClick={() => { setEditModel(null); setModal("model"); }}><Upload />Importar modelo</button><button className="btn primary" onClick={() => { setEditModel(null); setModal("model"); }}><Plus />Novo modelo</button></> : view === "credentials" ? <button className="btn primary" onClick={() => setModal("group")}><Plus />Nova lista</button> : view === "devices" ? <><button className="btn secondary" onClick={() => setModal("import")}><Upload />Importar CSV</button><button className="btn primary" onClick={() => navigate("agent")}><Play />Preparar lote{selected.length > 0 && ` (${selected.length})`}</button></> : view !== "acs" && view !== "agent" ? <button className="btn primary" onClick={() => view === "runs" ? openRun() : navigate("agent")}><Plus />{view === "runs" ? "Nova simulação" : "Preparar lote real"}</button> : null}</div></div>
      <div className={`demo-strip ${cloud.error ? "save-error" : ""}`}><ShieldCheck /><span><strong>{cloud.status}.</strong> {cloud.error || "Credenciais protegidas. Execuções reais disponíveis em Agente local."}</span>{cloud.error && <button onClick={() => cloud.flush().catch(()=>{})}>Tentar salvar</button>}</div>

      {view === "overview" && <>
        <div className="stats-grid"><Stat label="Equipamentos" value={devices.length} note="No inventário salvo" icon={<Network />} /><Stat label="Modelos cadastrados" value={models.length} note={`${prepared} roteiros cadastrados`} icon={<Router />} /><Stat label="Confirmados no ACS" value={confirmed} note={`${devices.length ? Math.round(confirmed / devices.length * 100) : 0}% do inventário`} icon={<CheckCheck />} green /><Stat label="Aguardando implantação" value={pending.length} note={`${devices.filter(d => d.status === "Revisar modelo").length} precisam revisar o modelo`} icon={<Clock3 />} /></div>
        <div className="overview-grid"><section className="panel rollout-panel"><div className="section-heading"><div className="section-title"><span className="mint-icon"><ListChecks /></span><div><h2>Prepare seu próximo lote</h2><p>Três etapas para iniciar a implantação.</p></div></div><Badge>01 — 03</Badge></div><div className="setup-steps">{[{ n: "01", title: "Modelos e roteiros", text: `${models.length} modelos · ${prepared} roteiros cadastrados`, icon: Router, target: "models" as View }, { n: "02", title: "Credenciais de acesso", text: `${groups.length} listas · ordem de tentativa definida`, icon: KeyRound, target: "credentials" as View }, { n: "03", title: "Equipamentos do lote", text: `${pending.length} equipamentos aguardando`, icon: Network, target: "devices" as View }].map(step => <button className="setup-step" key={step.n} onClick={() => navigate(step.target)}><span className="step-number">{step.n}</span><step.icon /><strong>{step.title}</strong><small>{step.text}</small><span className="step-link">Configurar<ArrowRight /></span></button>)}</div><div className="rollout-footer"><span><ShieldCheck />A execução segue o roteiro de cada modelo.</span><button className="btn primary" onClick={() => navigate("agent")}><Play />Preparar implantação</button></div></section><section className="destination-card"><div className="destination-top"><Server /><Badge tone="dark">DESTINO ACS</Badge></div><h2>{acs.name}</h2><p className="destination-url">{acs.url}</p><div className="destination-row"><span>Protocolo</span><strong>TR-069 / CWMP</strong></div><div className="destination-row"><span>Inform periódico</span><strong>{acs.interval} segundos</strong></div><div className="destination-row"><span>Verificação</span><span className="destination-state">{acs.verifier === "genieacs" ? "Consulta ao GenieACS" : "Conferência manual"}</span></div><button className="destination-link" onClick={() => navigate("acs")}>Configurar servidor<ArrowRight /></button></section></div>
        <section className="panel inventory-preview"><div className="section-heading"><div><h2>Fila de implantação</h2><p>Equipamentos que precisam de uma próxima ação.</p></div><button className="text-btn" onClick={() => navigate("devices")}>Ver todos os equipamentos<ArrowRight /></button></div>{pending.length ? renderDeviceTable(pending.slice(0, 5)) : <Empty title="Fila concluída" text="Todos os equipamentos de exemplo foram confirmados no ACS." />}<div className="table-footer"><span>Exibindo {Math.min(5, pending.length)} de {pending.length} pendentes</span><span><span className="legend-dot" />Inventário salvo</span></div></section>
      </>}

      {view === "models" && <><div className="toolbar"><div className="search-field"><Search /><input aria-label="Buscar modelos" placeholder="Buscar fabricante, modelo ou firmware..." value={query} onChange={e => setQuery(e.target.value)} />{query && <button aria-label="Limpar busca" onClick={() => setQuery("")}><X /></button>}</div><Pick label="Filtrar fabricante" value={brandFilter} onChange={setBrandFilter} items={[{ value: "all", label: "Todos os fabricantes" }, ...Array.from(new Set(models.map(m => m.brand))).map(b => ({ value: b, label: b }))]} /><span className="toolbar-count">{matchingModels.length} modelos</span></div><div className="models-grid">{matchingModels.map(m => <button key={m.id} className="model-card" onClick={() => setDetail(m)}><div className="model-top"><span className={`manufacturer-logo brand-${m.brand.toLowerCase().replaceAll(" ", "")}`}>{m.brand === "TP-Link" ? "tp" : m.brand === "Intelbras" ? "i" : m.brand.slice(0, 1)}</span><Badge>{m.type}</Badge></div><div className="model-name"><span>{m.brand}</span><h2>{m.name}</h2><p>{m.firmware}</p></div><div className="model-meta"><span><KeyRound />{groups.find(g => g.id === m.group)?.name || "Sem lista"}</span><span><Network />{devices.filter(d => d.model === m.id).length} equipamentos</span></div><div className="model-bottom"><Badge tone={m.ready ? "green" : "amber"}>{m.ready ? <Check /> : <Clock3 />}{m.example ? "Perfil ilustrativo" : m.ready ? "Roteiro cadastrado" : "Roteiro em rascunho"}</Badge><ChevronRight /></div></button>)}<button className="add-model-card" onClick={() => { setEditModel(null); setModal("model"); }}><span><Plus /></span><h3>Adicionar equipamento</h3><p>Cadastre um modelo ou importe<br />um roteiro em JSON.</p></button></div>{matchingModels.length === 0 && <p className="muted-note">Nenhum modelo corresponde aos filtros selecionados.</p>}<div className="context-note"><Fingerprint /><p><strong>O firmware também faz parte do modelo.</strong> Perfis ilustrativos não executam acessos. Cadastre os campos reais e valide cada firmware com o agente local.</p></div></>}

      {view === "credentials" && <><div className="credentials-layout"><aside className="panel group-list"><div className="section-heading"><h2>Listas de acesso</h2><Badge>{groups.length}</Badge></div>{groups.map(g => <button className={`group-item ${group.id === g.id ? "active" : ""}`} key={g.id} onClick={() => { setGroupId(g.id); setReveal([]); }}><KeyRound /><div><strong>{g.name}</strong><small>{g.entries.length} combinações cadastradas</small></div><ChevronRight /></button>)}<div className="group-foot"><LockKeyhole /><p>As senhas são criptografadas no servidor.<br />Senhas já salvas não são devolvidas ao navegador.</p></div></aside><section className="panel credentials-panel"><div className="section-heading"><div><span className="eyebrow">LISTA SELECIONADA</span><h2>{group.name}</h2><p>O bot para na primeira credencial válida.</p></div><button className="btn primary" onClick={() => setModal("credential")}><Plus />Adicionar credencial</button></div><div className="credential-table"><Table><TableHeader><TableRow><TableHead>Ordem</TableHead><TableHead>Identificação</TableHead><TableHead>Usuário / senha</TableHead><TableHead><span className="sr-only">Ações</span></TableHead></TableRow></TableHeader><TableBody>{group.entries.map((entry, i) => <TableRow key={entry.id}><TableCell><div className="priority-cell"><span>{String(i + 1).padStart(2, "0")}</span><div><button className="tiny-btn" disabled={i === 0} aria-label={`Subir ${entry.label}`} onClick={() => reorder(entry.id, -1)}><ArrowUp /></button><button className="tiny-btn" disabled={i === group.entries.length - 1} aria-label={`Descer ${entry.label}`} onClick={() => reorder(entry.id, 1)}><ArrowDown /></button></div></div></TableCell><TableCell><strong>{entry.label}</strong>{i === 0 && <small className="block green-text">Primeira tentativa</small>}</TableCell><TableCell><span className="mono">{entry.username}</span><div className="masked-password"><span className="mono">{reveal.includes(entry.id) ? entry.password : "••••••••••••"}</span><button className="icon-btn" disabled={!entry.password} aria-label={reveal.includes(entry.id) ? `Ocultar ${entry.label}` : `Mostrar ${entry.label}`} onClick={() => setReveal(r => r.includes(entry.id) ? r.filter(id => id !== entry.id) : [...r, entry.id])}>{reveal.includes(entry.id) ? <EyeOff /> : <Eye />}</button></div></TableCell><TableCell><button className="icon-btn delete-btn" aria-label={`Remover ${entry.label}`} onClick={() => { setGroups(gs => gs.map(g => g.id === group.id ? { ...g, entries: g.entries.filter(c => c.id !== entry.id) } : g)); toast("Credencial removida da lista."); }}><Trash2 /></button></TableCell></TableRow>)}</TableBody></Table></div>{!group.entries.length && <Empty title="Sua lista está vazia" text="Adicione a primeira combinação de usuário e senha." />}<div className="policy-panel"><div className="section-title"><ShieldCheck /><div><h3>Política de tentativas</h3><p>Ajuste conforme o bloqueio de login do firmware.</p></div></div><div className="form-grid"><Field label="Máximo por equipamento"><Pick label="Máximo de tentativas" value={String(group.attempts)} onChange={v => setGroups(gs => gs.map(g => g.id === group.id ? { ...g, attempts: Number(v) } : g))} items={[1, 2, 3, 4, 5].map(n => ({ value: String(n), label: `${n} tentativa${n > 1 ? "s" : ""}` }))} /></Field><Field label="Pausa mínima após falha"><Pick label="Pausa após falha" value={String(group.cooldown)} onChange={v => setGroups(gs => gs.map(g => g.id === group.id ? { ...g, cooldown: Number(v) } : g))} items={[30, 60, 120, 300].map(n => ({ value: String(n), label: `${n} segundos` }))} /></Field></div><div className="policy-foot"><CheckCircle2 />Ao atingir o limite, interromper o equipamento. Sem repetição automática.</div></div><div className="associated-models"><h3>Modelos associados</h3><div>{models.filter(m => m.group === group.id).map(m => <button key={m.id} onClick={() => setDetail(m)}>{m.brand} {m.name}<ChevronRight /></button>)}{!models.some(m => m.group === group.id) && <p>Nenhum modelo associado. Selecione esta lista no cadastro do modelo.</p>}</div></div></section></div></>}

      {view === "devices" && <section className="panel"><div className="inventory-filters"><Tabs value={deviceFilter} onValueChange={setDeviceFilter}><TabsList variant="line"><TabsTrigger value="all">Todos <span>{devices.length}</span></TabsTrigger><TabsTrigger value="pending">Pendentes <span>{pending.length}</span></TabsTrigger><TabsTrigger value="done">Confirmados <span>{confirmed}</span></TabsTrigger><TabsTrigger value="attention">Requer atenção</TabsTrigger></TabsList></Tabs><div className="search-field"><Search /><input aria-label="Buscar equipamentos" placeholder="Buscar IP, equipamento ou modelo..." value={query} onChange={e => setQuery(e.target.value)} /></div></div>{selected.length > 0 && <div className="selection-bar"><span><Check />{selected.length} equipamentos selecionados</span><button className="text-btn" onClick={() => setSelected([])}>Limpar seleção</button></div>}{filteredDevices.length ? renderDeviceTable(filteredDevices, true) : <Empty title="Nenhum equipamento encontrado" text="Ajuste a busca ou importe uma lista de equipamentos." />}<div className="table-footer"><span>{filteredDevices.length} equipamentos exibidos</span><button className="text-btn" onClick={() => setModal("import")}><FileUp />Importar novos equipamentos</button></div></section>}

      {view === "runs" && <>{runs.length === 0 ? <div className="panel first-run"><div className="first-run-icon"><Activity /></div><Badge tone="mint">EXECUÇÃO EM LOTE</Badge><h2>Veja a implantação acontecer.</h2><p>Escolha os equipamentos e acompanhe uma simulação<br />de acesso, configuração e confirmação no ACS.</p><div className="execution-stages">{["Acessar", "Autenticar", "Configurar", "Confirmar"].map((s, i) => <span key={s}><b>{i + 1}</b>{s}{i < 3 && <ChevronRight />}</span>)}</div><button className="btn primary" onClick={() => openRun()}><Play />Criar primeira simulação</button></div> : <><div className="run-picker"><Pick label="Selecionar execução" value={activeRun.id} onChange={setRunId} items={runs.map(r => ({ value: r.id, label: r.name }))} /><span>{activeRun.date}</span><Badge tone="mint">Resultados simulados</Badge></div><section className="panel run-summary"><div className="section-heading"><div><span className="eyebrow">{activeRun.mode === "validate" ? "VALIDAÇÃO DE ACESSO" : "IMPLANTAÇÃO ACS"}</span><h2>{activeRun.name}</h2></div><div className="heading-actions">{activeRun.state === "running" || activeRun.state === "paused" ? <><button className="btn secondary" onClick={() => setRuns(rs => rs.map(r => r.id === activeRun.id ? { ...r, state: r.state === "running" ? "paused" : "running" } : r))}>{activeRun.state === "running" ? <Pause /> : <Play />}{activeRun.state === "running" ? "Pausar" : "Retomar"}</button><button className="btn secondary" onClick={() => setRuns(rs => rs.map(r => r.id === activeRun.id ? { ...r, state: "cancelled" } : r))}><Square />Encerrar</button></> : <button className="btn secondary" onClick={() => exportRun(activeRun)}><Download />Exportar relatório</button>}</div></div><div className="run-progress-label"><span>{activeRun.state === "running" ? <Loader2 className="spin" /> : activeRun.state === "finished" ? <CheckCircle2 /> : <Pause />}{activeRun.state === "running" ? "Simulação em andamento" : activeRun.state === "paused" ? "Simulação pausada" : activeRun.state === "finished" ? "Simulação concluída" : "Simulação encerrada"}</span><strong>{activeRun.cursor} / {activeRun.results.length} equipamentos</strong></div><Progress value={activeRun.cursor / activeRun.results.length * 100} aria-label="Progresso da simulação" /><div className="run-counts"><div><span>Concluídos com sucesso</span><strong>{activeRun.results.slice(0, activeRun.cursor).filter(r => ["Confirmado no ACS", "Já configurado", "Acesso validado"].includes(r.status)).length}</strong></div><div><span>Aguardando ACS</span><strong>{activeRun.results.slice(0, activeRun.cursor).filter(r => r.status === "Aguardando ACS").length}</strong></div><div><span>Requer atenção</span><strong>{activeRun.results.slice(0, activeRun.cursor).filter(r => ["Falha de login", "Sem acesso", "Sem credencial", "Revisar modelo"].includes(r.status)).length}</strong></div><div><span>Na fila</span><strong>{activeRun.results.length - activeRun.cursor}</strong></div></div></section><section className="panel run-table"><div className="section-heading"><div><h2>Resultado por equipamento</h2><p>Abra um resultado para ver o motivo e a credencial utilizada.</p></div><ListChecks /></div><Table><TableHeader><TableRow><TableHead>Equipamento</TableHead><TableHead>Endereço IP</TableHead><TableHead>Modelo</TableHead><TableHead>Resultado simulado</TableHead><TableHead /></TableRow></TableHeader><TableBody>{activeRun.results.map((r, i) => <TableRow key={r.id}><TableCell><strong>{r.device}</strong></TableCell><TableCell><span className="mono">{r.ip}</span></TableCell><TableCell>{r.model}</TableCell><TableCell>{i < activeRun.cursor ? <Status value={r.status} /> : i === activeRun.cursor && activeRun.state === "running" ? <Badge tone="mint"><Loader2 className="spin" />Processando</Badge> : <Badge>{activeRun.state === "cancelled" ? "Não executado" : "Na fila"}</Badge>}</TableCell><TableCell><button className="icon-btn" disabled={i >= activeRun.cursor} aria-label={`Ver resultado de ${r.device}`} onClick={() => setResultDetail(r)}><ChevronRight /></button></TableCell></TableRow>)}</TableBody></Table></section></>}</>}

      {view === "agent" && <AgentPanel localMode={localMode} devices={devices} selected={selected} flush={cloud.flush} reload={cloud.reload} chooseDevices={() => navigate("devices")} />}
      {view === "acs" && <ACSForm current={acs} save={a => { setACS(a); toast.success("Parâmetros preparados. Salvando…"); }} />}
      <footer className="page-footer"><span>ACS Pilot <span className="footer-separator">/</span> Base funcional · piloto</span><span><LockKeyhole />Acesso privado · cadastros persistentes</span></footer>
    </main></SidebarInset>

    <Dialog open={modal !== null} onOpenChange={open => { if (!open) { setModal(null); setEditModel(null); } }}><DialogContent className={`pilot-dialog ${modal === "model" || modal === "import" || modal === "run" ? "wide-dialog" : ""}`}>
      {modal === "model" && <ModelForm initial={editModel} groups={groups} models={models} save={saveModel} close={() => setModal(null)} />}
      {modal === "group" && <GroupForm save={g => { setGroups(gs => [...gs, g]); setGroupId(g.id); setModal(null); toast.success("Lista criada. Salvando…"); }} />}
      {modal === "credential" && <CredentialForm group={group} save={entry => { setGroups(gs => gs.map(g => g.id === group.id ? { ...g, entries: [...g.entries, entry] } : g)); setModal(null); toast.success("Credencial adicionada. Salvando com criptografia…"); }} />}
      {modal === "import" && <ImportForm models={models} devices={devices} save={newDevices => { setDevices(ds => [...ds, ...newDevices]); setModal(null); toast.success(`${newDevices.length} equipamentos importados. Salvando…`); }} />}
      {modal === "run" && <RunForm targets={runTargets} models={models} acs={acs} count={runs.length} start={startRun} />}
      {modal === "help" && <><DialogHeader><DialogTitle>Explore o ACS Pilot</DialogTitle><DialogDescription>Cadastre os equipamentos e execute os lotes pelo agente instalado na sua rede.</DialogDescription></DialogHeader><div className="help-steps"><p><b>1</b><span><strong>Cadastre os modelos</strong>Importe um JSON ou edite um roteiro de acesso web.</span></p><p><b>2</b><span><strong>Organize as credenciais</strong>Crie listas, adicione senhas da sua operação e ajuste a prioridade.</span></p><p><b>3</b><span><strong>Selecione os equipamentos</strong>Use a lista de exemplo ou importe seu CSV de teste.</span></p><p><b>4</b><span><strong>Valide e implante</strong>Em Agente local, exporte um pacote de validação e importe o resultado. Depois gere o pacote de implantação.</span></p></div><div className="info-box"><FlaskConical /><p>Os cadastros são persistentes. As simulações continuam disponíveis separadamente. Somente o agente local realiza acessos reais, por meio dos pacotes que você exportar.</p></div><p className="muted-note">O primeiro roteiro real depende dos menus e campos do firmware usado na sua rede.</p><button className="btn primary full" onClick={() => setModal(null)}>Explorar plataforma<ArrowRight /></button></>}
    </DialogContent></Dialog>

    <Sheet open={!!detail} onOpenChange={open => { if (!open) setDetail(null); }}><SheetContent className="model-sheet">{detail && <><SheetHeader><span className="eyebrow">PERFIL DO EQUIPAMENTO</span><SheetTitle>{detail.brand} {detail.name}</SheetTitle><SheetDescription>{detail.type} · {detail.firmware}</SheetDescription></SheetHeader><div className="sheet-body"><div className="sheet-badges"><Badge tone={detail.ready ? "green" : "amber"}>{detail.example ? "Perfil ilustrativo" : detail.ready ? "Roteiro cadastrado" : "Rascunho"}</Badge><Badge>TR-069</Badge></div><Tabs defaultValue="flow"><TabsList><TabsTrigger value="flow">Roteiro de acesso</TabsTrigger><TabsTrigger value="config">Configuração</TabsTrigger></TabsList><TabsContent value="flow"><div className="flow-timeline">{[{ icon: Wifi, title: "Acessar interface web", text: `Abrir o endereço do equipamento em ${detail.loginPath || "(a definir)"}` }, { icon: KeyRound, title: "Validar credencial", text: groups.find(g => g.id === detail.group)?.name || "Nenhuma lista associada" }, { icon: Settings2, title: "Abrir configuração TR-069", text: detail.acsPath || "Caminho ainda não definido" }, { icon: Server, title: "Aplicar parâmetros do ACS", text: "URL, autenticação e Inform periódico" }, { icon: CheckCheck, title: "Conferir o resultado", text: "Reler configuração e aguardar nova comunicação com o ACS" }].map((step, i) => <div key={step.title}><span className="timeline-icon"><step.icon /></span><div><small>ETAPA 0{i + 1}</small><h3>{step.title}</h3><p>{step.text}</p></div></div>)}</div></TabsContent><TabsContent value="config"><dl className="detail-fields">{[["Página de login", detail.loginPath], ["Campo de usuário", detail.userSelector], ["Campo de senha", detail.passwordSelector], ["Botão de entrada", detail.submitSelector], ["Página do ACS", detail.acsPath], ["Campo URL do ACS", detail.acsSelector], ["Botão de salvar", detail.saveSelector]].map(([k, v]) => <div key={k}><dt>{k}</dt><dd>{v || "A definir"}</dd></div>)}</dl></TabsContent></Tabs><div className="info-box"><FlaskConical /><p>Menus e campos precisam ser conferidos no firmware real. A implantação só é liberada após importar a validação de acesso do equipamento.</p></div></div><div className="sheet-actions"><button className="btn secondary" onClick={() => { const { id, ...template } = detail; void id; download("modelo-acs.json", JSON.stringify(template, null, 2)); }}><Download />Exportar JSON</button><button className="btn primary" onClick={() => { setEditModel(detail); setDetail(null); setModal("model"); }}><Settings2 />Editar modelo</button></div></>}</SheetContent></Sheet>
    <Sheet open={!!resultDetail} onOpenChange={open => { if (!open) setResultDetail(null); }}><SheetContent className="model-sheet">{resultDetail && <><SheetHeader><span className="eyebrow">RESULTADO SIMULADO</span><SheetTitle>{resultDetail.device}</SheetTitle><SheetDescription>{resultDetail.ip} · {resultDetail.model}</SheetDescription></SheetHeader><div className="sheet-body"><Status value={resultDetail.status} /><div className="result-message"><h3>O que aconteceu</h3><p>{resultDetail.message}</p></div><dl className="detail-fields"><div><dt>Credencial utilizada</dt><dd>{resultDetail.credential || "Nenhuma validada"}</dd></div><div><dt>Origem do resultado</dt><dd>Cenário de demonstração</dd></div></dl><div className="info-box"><ShieldCheck /><p>Senhas não aparecem nos relatórios. “Aguardando ACS” significa que a comunicação ainda precisa ser confirmada.</p></div></div></>}</SheetContent></Sheet>
    <Toaster theme="light" position="bottom-right" richColors />
  </SidebarProvider>;
}

function Stat({ label, value, note, icon, green }: { label: string; value: number; note: string; icon: ReactNode; green?: boolean }) { return <section className={`stat-card ${green ? "highlight" : ""}`}><div><span>{label}</span><span className="stat-icon">{icon}</span></div><strong>{String(value).padStart(2, "0")}</strong><p>{green && <span className="legend-dot" />}{note}</p></section>; }

function ModelForm({ initial, groups, models, save, close }: { initial: Model | null; groups: Group[]; models: Model[]; save: (model: Model) => void; close: () => void }) {
  const [draft, setDraft] = useState<Model>(initial || { id: "", brand: "", name: "", type: "Roteador", firmware: "", group: groups[0]?.id || "", loginPath: "/", acsPath: "", userSelector: "", passwordSelector: "", submitSelector: "", acsSelector: "", saveSelector: "", ready: false });
  const [error, setError] = useState("");
  const [tab, setTab] = useState("general");
  const update = (key: keyof Model, value: string | boolean) => setDraft(d => ({ ...d, [key]: value }));
  const complete = !!(draft.loginPath.trim() && draft.acsPath.trim() && draft.userSelector.trim() && draft.passwordSelector.trim() && draft.submitSelector.trim() && draft.acsSelector.trim() && draft.saveSelector.trim());
  async function importFile(file?: File) {
    if (!file) return;
    if (file.size > 1_000_000) { setError("O JSON deve ter até 1 MB."); return; }
    try {
      const data = JSON.parse(await file.text());
      if (!data || typeof data !== "object" || Array.isArray(data) || typeof data.brand !== "string" || typeof data.name !== "string") throw new Error("O JSON precisa dos campos brand e name.");
      const next = { ...draft };
      for (const key of ["brand", "name", "firmware", "loginPath", "acsPath", "userSelector", "passwordSelector", "submitSelector", "acsSelector", "saveSelector", "successSelector", "failureSelector", "lockoutSelector", "identitySelector", "identityText", "firmwareSelector", "serialSelector", "acsUsernameSelector", "acsPasswordSelector", "enabledSelector", "periodicSelector", "intervalSelector", "frameSelector"] as const) if (typeof data[key] === "string") next[key] = data[key].slice(0, 300);
      next.type = data.type === "ONU" ? "ONU" : "Roteador";
      next.scheme = data.scheme === "https" ? "https" : "http";
      next.allowSelfSigned = data.allowSelfSigned === true;
      if (Array.isArray(data.navigation) && data.navigation.every((v: unknown) => typeof v === "string")) next.navigation = data.navigation.slice(0, 10);
      if (groups.some(g => g.id === data.group)) next.group = data.group;
      setDraft(next); setError(""); setTab("general"); toast.success("JSON carregado. Revise os dados e salve o modelo.");
    } catch (e) { setError(e instanceof Error ? e.message : "Não foi possível ler este JSON."); }
  }
  function submit() {
    if (!draft.brand.trim() || !draft.name.trim() || !draft.firmware.trim()) { setError("Preencha fabricante, modelo e firmware."); setTab("general"); return; }
    if (models.some(m => m.id !== initial?.id && `${m.brand}|${m.name}|${m.firmware}`.toLowerCase() === `${draft.brand.trim()}|${draft.name.trim()}|${draft.firmware.trim()}`.toLowerCase())) { setError("Já existe um cadastro para este fabricante, modelo e firmware."); return; }
    save({ ...draft, brand: draft.brand.trim(), name: draft.name.trim(), firmware: draft.firmware.trim(), id: initial?.id || uid("model"), ready: complete });
  }
  return <><DialogHeader><DialogTitle>{initial ? "Editar modelo" : "Adicionar modelo de equipamento"}</DialogTitle><DialogDescription>Cadastre o modelo e associe seu roteiro de acesso e credenciais.</DialogDescription></DialogHeader>{!initial && <label className="upload-strip"><FileJson /><span><strong>Já tem um roteiro?</strong> Importar arquivo JSON</span><input type="file" accept=".json,application/json" aria-label="Importar modelo JSON" onChange={e => importFile(e.target.files?.[0])} /><Upload /></label>}<Tabs value={tab} onValueChange={setTab}><TabsList><TabsTrigger value="general">1. Equipamento</TabsTrigger><TabsTrigger value="flow">2. Roteiro web</TabsTrigger></TabsList><TabsContent value="general"><div className="form-stack"><div className="form-grid"><Field label="Fabricante"><input value={draft.brand} placeholder="Ex.: TP-Link" maxLength={80} onChange={e => update("brand", e.target.value)} /></Field><Field label="Modelo"><input value={draft.name} placeholder="Ex.: Archer C5" maxLength={100} onChange={e => update("name", e.target.value)} /></Field><Field label="Tipo de equipamento"><Pick label="Tipo de equipamento" value={draft.type} onChange={v => update("type", v)} items={[{ value: "Roteador", label: "Roteador / CPE" }, { value: "ONU", label: "ONU / ONT" }]} /></Field><Field label="Firmware / versão"><input value={draft.firmware} maxLength={100} placeholder="Versão exata instalada" onChange={e => update("firmware", e.target.value)} /></Field></div><Field label="Lista de credenciais"><Pick label="Lista de credenciais" value={draft.group} onChange={v => update("group", v)} items={groups.map(g => ({ value: g.id, label: `${g.name} (${g.entries.length})` }))} /></Field><div className="info-box"><KeyRound /><p>A ordem das tentativas e o limite por equipamento seguem a lista selecionada.</p></div></div></TabsContent><TabsContent value="flow"><div className="form-stack"><div className="form-grid">{[["loginPath", "Página de login", "/"], ["acsPath", "Página de configuração ACS", "/menu/tr069"], ["userSelector", "Campo de usuário", "#usuario"], ["passwordSelector", "Campo de senha", "#senha"], ["submitSelector", "Botão de entrada", "#entrar"], ["acsSelector", "Campo da URL do ACS", "#acs-url"], ["saveSelector", "Botão de salvar", "#salvar"], ["successSelector", "Indicador de login concluído", "#painel-autenticado"], ["failureSelector", "Mensagem de credencial inválida", "#erro-login"], ["lockoutSelector", "Mensagem de bloqueio (opcional)", "#login-bloqueado"], ["identitySelector", "Texto com identificação do modelo", "#modelo"], ["identityText", "Identificação exata esperada", "Fabricante Modelo"], ["firmwareSelector", "Texto com a versão do firmware", "#firmware"], ["serialSelector", "Texto com o número de série", "#serie"], ["acsUsernameSelector", "Usuário CPE → ACS", "#acs-usuario"], ["acsPasswordSelector", "Senha CPE → ACS", "#acs-senha"], ["enabledSelector", "Checkbox TR-069 habilitado", "#tr069"], ["periodicSelector", "Checkbox Inform periódico", "#inform"], ["intervalSelector", "Intervalo do Inform", "#intervalo"], ["frameSelector", "Iframe da configuração (opcional)", "#config-frame"]].map(([key, label, placeholder]) => <Field key={key} label={label}><input value={String(draft[key as keyof Model] ?? "")} maxLength={300} placeholder={placeholder} onChange={e => update(key as keyof Model, e.target.value)} /></Field>)}</div><Field label="Protocolo da interface web"><Pick label="Protocolo" value={draft.scheme || "http"} onChange={v => update("scheme", v)} items={[{value:"http",label:"HTTP"},{value:"https",label:"HTTPS"}]} /></Field><label className="switch-row"><span>Permitir certificado autoassinado neste modelo</span><Switch checked={!!draft.allowSelfSigned} onCheckedChange={v => update("allowSelfSigned",v)} /></label><Field label="Cliques após abrir a página ACS (um seletor por linha)"><textarea rows={3} value={(draft.navigation || []).join("\n")} onChange={e => setDraft(d => ({...d,navigation:e.target.value.split("\n").filter(Boolean).slice(0,10)}))} /></Field><p className="muted-note">Use seletores CSS únicos. A identidade e o firmware devem corresponder exatamente ao texto exibido pelo equipamento. O agente inicial suporta login por formulário HTML e habilitações por checkbox.</p></div></TabsContent></Tabs>{error && <p className="form-error" role="alert">{error}</p>}<div className="dialog-footer"><span className="draft-note">{complete ? <CheckCircle2 /> : <Clock3 />}{complete ? "Pronto para simular" : "Será salvo como rascunho"}</span><button className="btn secondary" onClick={close}>Cancelar</button><button className="btn primary" onClick={submit}><Check />Salvar modelo</button></div></>;
}

function GroupForm({ save }: { save: (g: Group) => void }) {
  const [name, setName] = useState("");
  return <form onSubmit={e => { e.preventDefault(); if (name.trim()) save({ id: uid("group"), name: name.trim(), attempts: 3, cooldown: 60, entries: [] }); }}><DialogHeader><DialogTitle>Nova lista de credenciais</DialogTitle><DialogDescription>Agrupe acessos por fabricante, lote ou período de instalação.</DialogDescription></DialogHeader><div className="form-stack"><Field label="Nome da lista"><input required maxLength={80} value={name} onChange={e => setName(e.target.value)} placeholder="Ex.: Instalações fibra 2026" /></Field><p className="muted-note">Depois, adicione as combinações de usuário e senha e associe a lista aos modelos.</p><button className="btn primary full" type="submit"><Plus />Criar lista</button></div></form>;
}
function CredentialForm({ group, save }: { group: Group; save: (c: Credential) => void }) {
  const [label, setLabel] = useState(""), [username, setUsername] = useState(""), [password, setPassword] = useState("");
  return <form onSubmit={e => { e.preventDefault(); if (!label.trim() || !username.trim()) { toast.error("Preencha identificação e usuário."); return; } if (!password) { toast.error("Informe a senha para adicionar esta credencial."); return; } if (group.entries.some(c => c.username === username.trim() && c.password === password)) { toast.error("Esta combinação já está nesta lista."); return; } save({ id: uid("credential"), label: label.trim(), username: username.trim(), password }); }}><DialogHeader><DialogTitle>Adicionar credencial</DialogTitle><DialogDescription>{group.name} · tentativa {group.entries.length + 1}</DialogDescription></DialogHeader><div className="form-stack"><Field label="Identificação"><input required maxLength={80} value={label} onChange={e => setLabel(e.target.value)} placeholder="Ex.: Instalações anteriores" /></Field><Field label="Usuário"><input required maxLength={100} autoComplete="off" value={username} onChange={e => setUsername(e.target.value)} placeholder="Usuário da interface web" /></Field><Field label="Senha"><Secret value={password} onChange={setPassword} /></Field><div className="info-box"><LockKeyhole /><p>A senha será criptografada no servidor e incluída somente nos pacotes dos lotes associados.</p></div><button className="btn primary full" type="submit"><Plus />Adicionar à lista</button></div></form>;
}

function ImportForm({ models, devices, save }: { models: Model[]; devices: Device[]; save: (ds: Device[]) => void }) {
  const [preview, setPreview] = useState<{ devices: Device[]; errors: string[] } | null>(null);
  const [fileName, setFileName] = useState("");
  const [error, setError] = useState("");
  async function read(file?: File) {
    if (!file) return; setPreview(null); setError(""); setFileName(file.name);
    if (file.size > 2_000_000) { setError("O CSV de demonstração deve ter até 2 MB."); return; }
    try { const result = previewCSV(await file.text(), models, devices); if (result.devices.length > 2000) throw new Error("Importe até 2.000 equipamentos por vez nesta versão."); setPreview(result); } catch (e) { setError(e instanceof Error ? e.message : "Falha ao ler CSV."); }
  }
  return <><DialogHeader><DialogTitle>Importar equipamentos</DialogTitle><DialogDescription>Envie uma lista CSV e confira os dados antes de adicionar ao inventário.</DialogDescription></DialogHeader><label className="dropzone"><span><FileUp /></span><strong>{fileName || "Selecione seu arquivo CSV"}</strong><p>Colunas: nome, ip, porta, modelo · até 2 MB</p><input type="file" accept=".csv,text/csv" aria-label="Selecionar arquivo CSV" onChange={e => read(e.target.files?.[0])} /><span className="btn secondary">Escolher arquivo</span></label><button className="text-btn template-download" onClick={() => download("equipamentos-exemplo.csv", `nome;ip;porta;modelo\nCPE-TESTE-01;192.0.2.101;80;${models[0]?.name || "Archer C5"}\nCPE-TESTE-02;192.0.2.102;80;${models[1]?.name || "HG8245H"}\n`, "text/csv;charset=utf-8")}><Download />Baixar CSV de exemplo</button>{error && <p className="form-error" role="alert">{error}</p>}{preview && <div className="import-preview"><div className="section-heading"><h3>Prévia da importação</h3><Badge tone={preview.errors.length ? "amber" : "green"}>{preview.devices.length} válidos · {preview.errors.length} erros</Badge></div>{preview.devices.slice(0, 4).map(d => <div className="import-row" key={d.id}><strong>{d.name}</strong><span className="mono">{d.ip}:{d.port}</span><CheckCircle2 /></div>)}{preview.errors.slice(0, 5).map(e => <p className="form-error" key={e}>{e}</p>)}{preview.errors.length > 5 && <p className="form-error">E mais {preview.errors.length - 5} erros. Corrija o arquivo e envie novamente.</p>}<p className="muted-note">{preview.errors.length ? "Corrija todas as linhas com erro para importar o arquivo completo." : "O modelo de cada linha será associado ao cadastro existente."}</p></div>}<div className="dialog-footer"><span className="muted-note">Nenhum acesso será realizado.</span><button className="btn primary" disabled={!preview?.devices.length || !!preview?.errors.length} onClick={() => preview && save(preview.devices)}><Upload />Importar {preview?.devices.length || ""} equipamentos</button></div></>;
}

function RunForm({ targets, models, acs, count, start }: { targets: Device[]; models: Model[]; acs: ACS; count: number; start: (name: string, mode: string) => void }) {
  const [name, setName] = useState(`Implantação ${String(count + 1).padStart(2, "0")} • lote de teste`);
  const [mode, setMode] = useState("provision");
  const unready = targets.filter(d => !models.find(m => m.id === d.model)?.ready).length;
  return <form onSubmit={e => { e.preventDefault(); if (name.trim()) start(name.trim(), mode); }}><DialogHeader><DialogTitle>Nova execução</DialogTitle><DialogDescription>Revise o lote e escolha o cenário que deseja simular.</DialogDescription></DialogHeader><div className="form-stack"><Field label="Nome da execução"><input required maxLength={100} value={name} onChange={e => setName(e.target.value)} /></Field><div className="batch-recap"><div><Network /><span>Equipamentos</span><strong>{targets.length}</strong></div><div><Router /><span>Modelos no lote</span><strong>{new Set(targets.map(d => d.model)).size}</strong></div><div><Server /><span>Destino</span><strong>{acs.name}</strong></div></div><RadioGroup value={mode} onValueChange={setMode} className="mode-options"><label className={mode === "validate" ? "selected" : ""}><RadioGroupItem value="validate" /><div><strong>Validar acesso</strong><p>Simular login e leitura da configuração atual.</p></div><KeyRound /></label><label className={mode === "provision" ? "selected" : ""}><RadioGroupItem value="provision" /><div><strong>Implantar ACS</strong><p>Simular acesso, gravação e confirmação no ACS.</p></div><Play /></label></RadioGroup>{unready > 0 && <div className="info-box amber-box"><AlertTriangle /><p>{unready} equipamento(s) têm roteiro incompleto. Serão marcados para revisão, sem tentativa de acesso.</p></div>}<div className="info-box"><FlaskConical /><p>Simulação acelerada com cenários de exemplo. Nenhuma senha será testada e nenhum roteador será alterado.</p></div><button className="btn primary full" type="submit" disabled={mode === "provision" && !acs.enabled}><Play />Iniciar simulação</button>{!acs.enabled && mode === "provision" && <p className="form-error">Habilite o TR-069 na configuração do servidor ACS.</p>}</div></form>;
}

function ACSForm({ current, save }: { current: ACS; save: (acs: ACS) => void }) {
  const [draft, setDraft] = useState(current);
  const [saved, setSaved] = useState(true);
  function update(key: keyof ACS, value: string | number | boolean) { setDraft(d => ({ ...d, [key]: value })); setSaved(false); }
  return <div className="acs-layout"><form className="panel acs-form" onSubmit={e => { e.preventDefault(); try { const u = new URL(draft.url); if (!["http:", "https:"].includes(u.protocol) || u.username || u.password) throw new Error(); } catch { toast.error("Informe uma URL HTTP ou HTTPS válida, sem credenciais no endereço."); return; } if (!draft.name.trim() || !Number.isInteger(draft.interval) || draft.interval < 1) return; save({ ...draft, name: draft.name.trim() }); setSaved(true); }}><div className="section-heading"><div className="section-title"><span className="mint-icon"><Server /></span><div><h2>Parâmetros de conexão</h2><p>Aplicados pelos roteiros de cada modelo.</p></div></div><Badge>{saved ? "Parâmetros cadastrados" : "Alterações pendentes"}</Badge></div><div className="form-stack"><Field label="Nome do servidor"><input required maxLength={100} value={draft.name} onChange={e => update("name", e.target.value)} /></Field><Field label="URL do ACS" hint="Endereço completo de comunicação CWMP, incluindo caminho e porta quando necessário."><input required type="url" maxLength={500} value={draft.url} onChange={e => update("url", e.target.value)} /></Field><div className="field-divider" /><div><h3>Autenticação CPE → ACS</h3><p className="muted-note">Credenciais de comunicação com o servidor, separadas do login web do roteador.</p></div><div className="form-grid"><Field label="Usuário do ACS"><input autoComplete="off" maxLength={100} value={draft.username} onChange={e => update("username", e.target.value)} /></Field><Field label="Senha do ACS"><Secret value={draft.password} onChange={v => update("password", v)} label="Senha do ACS" /></Field></div><Field label="Confirmação no ACS"><Pick label="Método de confirmação" value={draft.verifier || "manual"} onChange={v => update("verifier", v)} items={[{value:"manual",label:"Conferir no ACS manualmente"},{value:"genieacs",label:"Consultar API do GenieACS"}]} /></Field>{draft.verifier === "genieacs" && <><Field label="URL da API NBI do GenieACS"><input type="url" required value={draft.nbiUrl || ""} onChange={e => update("nbiUrl",e.target.value)} placeholder="https://gestao.exemplo.com/nbi" /></Field><Field label="Token Bearer do proxy da API (se houver)"><Secret label="Token da API" value={draft.nbiToken || ""} onChange={v => update("nbiToken",v)} /></Field><p className="muted-note">A API NBI é diferente da URL CWMP. Importe a coluna acs_id com o ID exato do equipamento. O token é opcional e depende da proteção configurada no seu proxy.</p></>}<Field label="Intervalo do Inform periódico (segundos)"><input required type="number" min={1} max={604800} step={1} value={draft.interval || ""} onChange={e => update("interval", Number(e.target.value))} /></Field><div className="switch-row"><div><strong>Habilitar TR-069</strong><p>Ativar o gerenciamento remoto nos equipamentos do lote.</p></div><Switch aria-label="Habilitar TR-069" checked={draft.enabled} onCheckedChange={v => update("enabled", v)} /></div></div><div className="form-actions"><span><LockKeyhole />Credenciais criptografadas no servidor</span><button className="btn primary" type="submit"><Check />Salvar parâmetros</button></div></form><aside><section className="panel acs-explainer"><span className="mint-icon"><Cable /></span><h2>Dois acessos diferentes</h2><div><KeyRound /><h3>Interface web do equipamento</h3><p>O bot utiliza as listas em <strong>Credenciais de acesso</strong> para entrar no roteador ou ONU.</p></div><div><Server /><h3>Comunicação com o ACS</h3><p>O equipamento utiliza os parâmetros desta tela para se comunicar com o servidor.</p></div><div className="info-box"><CheckCheck /><p>A confirmação depende de uma nova comunicação do equipamento com o ACS.</p></div></section><div className="context-note"><Terminal /><p>O agente que acessa os equipamentos precisa rodar em uma máquina com conexão à sua rede.</p></div></aside></div>;
}
